// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *FAAllocation) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *FAAllocation) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var codeVal types.Code
		if v, exists := pkMap["code"]; exists {
			switch val := v.(type) {
			case types.Code:
				codeVal = val
			case string:
				codeVal = types.NewCode(val)
			}
		}
		var line_noVal int
		if v, exists := pkMap["line_no"]; exists {
			switch val := v.(type) {
			case int:
				line_noVal = val
			case float64:
				line_noVal = int(val)
			case string:
				// the key part as text: the API's "CUSTOMER1,10000"
				if n, err := strconv.Atoi(strings.TrimSpace(val)); err == nil {
					line_noVal = n
				}
			}
		}
		var allocation_typeVal FAAllocationAllocation_type
		if v, exists := pkMap["allocation_type"]; exists {
			switch val := v.(type) {
			case FAAllocationAllocation_type:
				allocation_typeVal = val
			case int:
				allocation_typeVal = FAAllocationAllocation_type(val)
			case float64:
				allocation_typeVal = FAAllocationAllocation_type(int(val))
			case string:
				if n, err := strconv.Atoi(val); err == nil {
					allocation_typeVal = FAAllocationAllocation_type(n)
				}
			}
		}
		return t.GetByPK(codeVal, line_noVal, allocation_typeVal)
	}
	// For tables with composite keys, direct value is not supported
	// Use a map[string]interface{} with field names as keys

	fmt.Printf("Error: Invalid primary key type for FA_Allocation.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *FAAllocation) GetByPK(code types.Code, line_no int, allocation_type FAAllocationAllocation_type) bool {
	tableName := fmt.Sprintf("%s$%s", t.company, FAAllocationTableName)
	var codeNull sql.NullString
	var line_noVal int
	var descriptionNull sql.NullString
	var account_noNull sql.NullString
	var dimension_1_codeNull sql.NullString
	var dimension_2_codeNull sql.NullString
	var allocation_percentNull sql.NullString
	var allocation_typeInt int

	// Collect arguments for query
	args := []interface{}{
		code,
		line_no,
		allocation_type,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT code, line_no, description, account_no, dimension_1_code, dimension_2_code, allocation_percent, allocation_type FROM "%s" WHERE 1=1 AND code = ? AND line_no = ? AND allocation_type = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&codeNull,
		&line_noVal,
		&descriptionNull,
		&account_noNull,
		&dimension_1_codeNull,
		&dimension_2_codeNull,
		&allocation_percentNull,
		&allocation_typeInt,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get FA_Allocation: %v\n", err)
		return false
	}

	// Populate fields
	t.Code = types.NewCode(codeNull.String)
	t.Line_no = line_noVal
	t.Description = types.NewText(descriptionNull.String)
	t.Account_no = types.NewCode(account_noNull.String)
	t.Dimension_1_code = types.NewCode(dimension_1_codeNull.String)
	t.Dimension_2_code = types.NewCode(dimension_2_codeNull.String)
	t.Allocation_percent, _ = types.NewDecimalFromString(allocation_percentNull.String)
	t.Allocation_type = FAAllocationAllocation_type(allocation_typeInt)

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *FAAllocation) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAAllocationTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Code,
		t.Line_no,
		t.Description,
		t.Account_no,
		t.Dimension_1_code,
		t.Dimension_2_code,
		t.Allocation_percent,
		t.Allocation_type,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (code, line_no, description, account_no, dimension_1_code, dimension_2_code, allocation_percent, allocation_type) VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (code, line_no, allocation_type) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert FA_Allocation: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(FAAllocationTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *FAAllocation) InsertAll(records []*FAAllocation, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Code,
			r.Line_no,
			r.Description,
			r.Account_no,
			r.Dimension_1_code,
			r.Dimension_2_code,
			r.Allocation_percent,
			r.Allocation_type,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAAllocationTableName)
	columns := []string{"code", "line_no", "description", "account_no", "dimension_1_code", "dimension_2_code", "allocation_percent", "allocation_type"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *FAAllocation) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			keyChanged = true
		}
		if t.hasFieldChanged("line_no") {
			keyChanged = true
		}
		if t.hasFieldChanged("allocation_type") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAAllocationTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			setClauses = append(setClauses, "code = ?")
			values = append(values, t.Code)
		}
		if t.hasFieldChanged("line_no") {
			setClauses = append(setClauses, "line_no = ?")
			values = append(values, t.Line_no)
		}
		if t.hasFieldChanged("description") {
			setClauses = append(setClauses, "description = ?")
			values = append(values, t.Description)
		}
		if t.hasFieldChanged("account_no") {
			setClauses = append(setClauses, "account_no = ?")
			values = append(values, t.Account_no)
		}
		if t.hasFieldChanged("dimension_1_code") {
			setClauses = append(setClauses, "dimension_1_code = ?")
			values = append(values, t.Dimension_1_code)
		}
		if t.hasFieldChanged("dimension_2_code") {
			setClauses = append(setClauses, "dimension_2_code = ?")
			values = append(values, t.Dimension_2_code)
		}
		if t.hasFieldChanged("allocation_percent") {
			setClauses = append(setClauses, "allocation_percent = ?")
			values = append(values, t.Allocation_percent)
		}
		if t.hasFieldChanged("allocation_type") {
			setClauses = append(setClauses, "allocation_type = ?")
			values = append(values, t.Allocation_type)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "description = ?")
		values = append(values, t.Description)
		setClauses = append(setClauses, "account_no = ?")
		values = append(values, t.Account_no)
		setClauses = append(setClauses, "dimension_1_code = ?")
		values = append(values, t.Dimension_1_code)
		setClauses = append(setClauses, "dimension_2_code = ?")
		values = append(values, t.Dimension_2_code)
		setClauses = append(setClauses, "allocation_percent = ?")
		values = append(values, t.Allocation_percent)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Code)
	}
	if old, ok := t.oldValues["line_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Line_no)
	}
	if old, ok := t.oldValues["allocation_type"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Allocation_type)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND code = ? AND line_no = ? AND allocation_type = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify FA_Allocation: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *FAAllocation) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Code.Equal(old)
		}
	case "line_no":
		if old, ok := oldValue.(int); ok {
			return t.Line_no != old
		}
		return true // Type mismatch, assume changed
	case "description":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Description.Equal(old)
		}
	case "account_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Account_no.Equal(old)
		}
	case "dimension_1_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Dimension_1_code.Equal(old)
		}
	case "dimension_2_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Dimension_2_code.Equal(old)
		}
	case "allocation_percent":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Allocation_percent.Equal(old)
		}
	case "allocation_type":
		if old, ok := oldValue.(FAAllocationAllocation_type); ok {
			return t.Allocation_type != old
		}
	}

	return false
}

