// ========================================
// FlowField Calculations
// ========================================

// CalcFields calculates FlowField values
// Usage:
//
//	customer.CalcFields("balance", "balance_lcy") - Calculate specific fields
//	customer.CalcFields() - Calculate all FlowFields
func (t *FAAllocation) CalcFields(fieldNames ...string) {
	// If no field names specified, calculate all FlowFields
	if len(fieldNames) == 0 {
		t.calcFlowField_account_name()
		return
	}

	// Calculate only specified fields
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "account_name":
			t.calcFlowField_account_name()
		}
	}
}

// calcFlowField_account_name calculates the account_name FlowField
// CalcFormula: Lookup(GLAccount.name)
func (t *FAAllocation) calcFlowField_account_name() {
	t.Account_name = t.calcLookup_account_name()
}

// CalcFieldsForRecords calculates FlowFields for many records at once (list pages):
// one grouped query per FlowField instead of one query per record. records are
// ToMap() results; each gets its FlowField values under the field name. With no
// field names, all FlowFields are calculated.
func (t *FAAllocation) CalcFieldsForRecords(records []map[string]interface{}, fieldNames ...string) {
	if len(records) == 0 {
		return
	}
	if len(fieldNames) == 0 {
		fieldNames = t.GetFlowFields()
	}
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "account_name":
			t.calcForRecords_account_name(records)
		}
	}
}

// calcForRecords_account_name calculates the account_name FlowField for a set of records
// CalcFormula: Lookup(GLAccount.name)
func (t *FAAllocation) calcForRecords_account_name(records []map[string]interface{}) {
	// No single key field to group by: calculate per record, with this record's FlowFilters
	for _, rec := range records {
		r := &FAAllocation{db: t.db, company: t.company, dbType: t.dbType}
		r.FromMap(rec)
		r.calcFlowField_account_name()
		rec["account_name"] = r.Account_name
	}
}

// Helper methods for FlowField calculations

// calcLookup_account_name reads GLAccount.name of the first record matching the
// flow filters (CalcFormula Lookup); blank when there is none
func (t *FAAllocation) calcLookup_account_name() types.Text {
	tableName := fmt.Sprintf("%s$%s", t.company, GLAccountTableName)
	var whereClauses []string
	var args []interface{}
	whereClauses = append(whereClauses, "no = ?")
	args = append(args, t.Account_no)
	whereClause := "1=1"
	if len(whereClauses) > 0 {
		whereClause = strings.Join(whereClauses, " AND ")
	}
	query := t.convertPlaceholders(fmt.Sprintf(`SELECT name FROM "%s" WHERE %s LIMIT 1`, tableName, whereClause), len(args))
	var value sql.NullString
	if err := t.db.QueryRow(query, args...).Scan(&value); err != nil && err != sql.ErrNoRows {
		fmt.Printf("Error: Failed to look up account_name: %v\n", err)
	}
	return types.NewText(value.String)
}

// ========================================
// Filtering and Search
// ========================================

// fAAllocationFilterCondition represents a filter on a field
type fAAllocationFilterCondition struct {
	fieldName    string
	minValue     interface{}
	maxValue     interface{}
	filterExpr   string // For complex SetFilter expressions
	isExpression bool   // True if using filterExpr instead of min/max
	invalidField bool   // Filter on an unknown field: matches no rows (fail closed)
	blankDate    bool   // A date range from the blank date: blank dates (NULL) match too
}

// SetRange sets a range filter on a field
// Usage:
//
//	SetRange("No", "10000") - exact match (No = "10000")
//	SetRange("No", "10000", "20000") - range (No between "10000" and "20000")
//	SetRange("No") - removes the filter on the field
func (t *FAAllocation) SetRange(fieldName string, values ...interface{}) {
	if t.filters == nil {
		t.filters = make(map[string]*fAAllocationFilterCondition)
	}

	var minValue, maxValue interface{}

	switch len(values) {
	case 0:
		if column, ok := t.columnName(fieldName); ok {
			delete(t.filters, column)
		}
		delete(t.filters, fieldName)
		return
	case 1:
		// Exact match: SetRange("No", "10000")
		minValue = values[0]
		maxValue = values[0]
	case 2:
		// Range: SetRange("No", "10000", "20000")
		minValue = values[0]
		maxValue = values[1]
	default:
		fmt.Printf("Error: SetRange requires 1 or 2 values, got %d\n", len(values))
		return
	}

	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetRange on unknown field %q of FA_Allocation\n", fieldName)
		t.filters[fieldName] = &fAAllocationFilterCondition{invalidField: true}
		return
	}

	// Blank dates are stored as NULL and come before every date: a range from the blank date
	// (or the blank date itself) matches them; a range up to the blank date (0D..0D) is the
	// blank date only
	blankDate := false
	if d, ok := values[0].(types.Date); ok && d.IsZero() {
		blankDate = true
		minValue = nil
		if len(values) == 1 {
			maxValue = nil
		}
		if to, ok := maxValue.(types.Date); ok && to.IsZero() {
			maxValue = nil
		}
	}

	t.filters[column] = &fAAllocationFilterCondition{
		fieldName: column,
		minValue:  minValue,
		maxValue:  maxValue,
		blankDate: blankDate,
	}
}

// SetFilter sets a complex filter expression on a field
// Supports filter syntax: "100..200|500" (range OR exact value)
// Operators: .. (range), | (OR), & (AND), * (wildcard), <> (not equal)
// Example: customer.SetFilter("No", "001..003|005")
func (t *FAAllocation) SetFilter(fieldName, filterExpr string) {
	if t.filters == nil {
		t.filters = make(map[string]*fAAllocationFilterCondition)
	}
	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetFilter on unknown field %q of FA_Allocation\n", fieldName)
		t.filters[fieldName] = &fAAllocationFilterCondition{invalidField: true}
		return
	}
	t.filters[column] = &fAAllocationFilterCondition{
		fieldName:    column,
		filterExpr:   filterExpr,
		isExpression: true,
	}
}

// SetCurrentKey sets the sort order for queries
